[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Page Not Found — IdeaForum</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet" />
  <style>
    /* ─── Design Tokens ─────────────────────────────────────────────── */
    :root {
      --brand-red:      oklch(44% 0.22 27);    /* #EB0028 equivalent  */
      --text-primary:   oklch(11% 0.01 270);   /* #121212             */
      --text-secondary: oklch(46% 0.01 270);   /* #696969             */
      --text-muted:     oklch(52% 0.01 270);   /* #777777             */
      --text-link:      oklch(52% 0.01 270);   /* links #777777       */
      --bg-page:        oklch(100% 0 0);        /* #FFFFFF             */
      --bg-code-bar:    oklch(96% 0.005 270);  /* light gray bar      */
      --border-subtle:  oklch(88% 0.01 270);   /* input/divider       */
      --border-input:   oklch(80% 0.01 270);   /* input border        */

      --radius-sm:  4px;
      --radius-md:  8px;

      --space-xs:   8px;
      --space-sm:   16px;
      --space-md:   24px;
      --space-lg:   40px;
      --space-xl:   64px;
      --space-2xl:  96px;

      --font-base: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }

    /* ─── Reset ─────────────────────────────────────────────────────── */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { font-size: 16px; -webkit-text-size-adjust: 100%; }

    body {
      font-family: var(--font-base);
      background: var(--bg-page);
      color: var(--text-primary);
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      align-items: center;
    }

    /* ─── Page Wrapper ───────────────────────────────────────────────── */
    .page-wrapper {
      flex: 1;
      width: 100%;
      display: flex;
      flex-direction: column;
      align-items: center;
      padding: var(--space-xl) var(--space-sm) var(--space-2xl);
    }

    /* ─── Logo ───────────────────────────────────────────────────────── */
    .logo-block {
      margin-bottom: var(--space-xl);
    }

    .logo-wordmark {
      display: inline-flex;
      align-items: baseline;
      gap: 0;
      font-size: clamp(2rem, 6vw, 3.25rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1;
      color: var(--brand-red);
      text-decoration: none;
      user-select: none;
    }

    /* The missing-E letterform: dashed outline box */
    .logo-wordmark .missing-e {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      width: 0.56em;
      height: 0.82em;
      border: 0.07em dashed var(--brand-red);
      border-radius: 2px;
      opacity: 0.55;
      margin: 0 0.01em;
      position: relative;
      top: 0.04em;
    }

    /* ─── Main Content ───────────────────────────────────────────────── */
    .content-block {
      width: 100%;
      max-width: 560px;
      display: flex;
      flex-direction: column;
      align-items: flex-start;
    }

    /* Apology heading */
    .error-heading {
      font-size: clamp(1.5rem, 4vw, 2rem);
      font-weight: 700;
      letter-spacing: -0.02em;
      color: var(--text-primary);
      line-height: 1.2;
      margin-bottom: var(--space-xs);
    }

    /* Sub-line */
    .error-subline {
      font-size: 1rem;
      font-weight: 400;
      color: var(--text-secondary);
      line-height: 1.6;
      margin-bottom: var(--space-md);
    }

    /* ─── Search ─────────────────────────────────────────────────────── */
    .search-form {
      width: 100%;
      margin-bottom: var(--space-md);
    }

    .search-field {
      position: relative;
      display: flex;
      align-items: center;
    }

    .search-input {
      width: 100%;
      height: 48px;
      padding: 0 52px 0 var(--space-sm);
      font-family: var(--font-base);
      font-size: 0.9375rem;
      font-weight: 400;
      color: var(--text-primary);
      background: var(--bg-page);
      border: 1.5px solid var(--border-input);
      border-radius: var(--radius-sm);
      outline: none;
      transition: border-color 0.15s ease;
      appearance: none;
    }

    .search-input::placeholder {
      color: var(--text-muted);
    }

    .search-input:focus {
      border-color: var(--text-primary);
    }

    .search-btn {
      position: absolute;
      right: 0;
      top: 0;
      height: 48px;
      width: 48px;
      background: none;
      border: none;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--text-muted);
      transition: color 0.15s ease;
      border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
    }

    .search-btn:hover { color: var(--text-primary); }
    .search-btn:focus-visible {
      outline: 2px solid var(--text-primary);
      outline-offset: -2px;
      border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
    }

    .search-btn svg {
      width: 18px;
      height: 18px;
      stroke-width: 2;
    }

    /* ─── Error Code Bar ─────────────────────────────────────────────── */
    .error-code-bar {
      width: 100%;
      background: var(--bg-code-bar);
      border-radius: var(--radius-sm);
      padding: 10px var(--space-sm);
      margin-bottom: var(--space-md);
    }

    .error-code-text {
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--text-muted);
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

    /* ─── Divider ────────────────────────────────────────────────────── */
    .divider {
      width: 100%;
      height: 1px;
      background: var(--border-subtle);
      margin-bottom: var(--space-md);
    }

    /* ─── Next Steps ─────────────────────────────────────────────────── */
    .next-steps-heading {
      font-size: 0.9375rem;
      font-weight: 600;
      color: var(--text-primary);
      margin-bottom: var(--space-xs);
      letter-spacing: -0.01em;
    }

    .next-steps-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 6px;
    }

    .next-steps-links a {
      font-size: 0.9375rem;
      font-weight: 400;
      color: var(--text-link);
      text-decoration: underline;
      text-underline-offset: 3px;
      text-decoration-color: oklch(75% 0.01 270);
      transition: color 0.15s ease, text-decoration-color 0.15s ease;
    }

    .next-steps-links a:hover {
      color: var(--text-primary);
      text-decoration-color: var(--text-primary);
    }

    .next-steps-links a:focus-visible {
      outline: 2px solid var(--text-primary);
      outline-offset: 2px;
      border-radius: 2px;
    }

    /* ─── Cookie Banner ──────────────────────────────────────────────── */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: var(--bg-page);
      border-top: 1px solid var(--border-subtle);
      padding: var(--space-sm) var(--space-md);
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: var(--space-sm);
      z-index: 100;
      box-shadow: 0 -2px 12px oklch(0% 0 0 / 0.06);
    }

    .cookie-banner[hidden] { display: none; }

    .cookie-text {
      font-size: 0.8125rem;
      color: var(--text-secondary);
      line-height: 1.5;
      flex: 1;
      min-width: 0;
    }

    .cookie-text a {
      color: var(--text-secondary);
      text-decoration: underline;
      text-underline-offset: 2px;
    }

    .cookie-text a:hover { color: var(--text-primary); }

    .cookie-actions {
      display: flex;
      gap: var(--space-xs);
      flex-shrink: 0;
      align-items: center;
    }

    .btn-cookie-manage {
      font-family: var(--font-base);
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--text-primary);
      background: none;
      border: 1.5px solid var(--border-input);
      border-radius: var(--radius-sm);
      padding: 7px 14px;
      cursor: pointer;
      white-space: nowrap;
      transition: border-color 0.15s, background 0.15s;
    }

    .btn-cookie-manage:hover {
      background: var(--bg-code-bar);
      border-color: var(--text-muted);
    }

    .btn-cookie-manage:focus-visible {
      outline: 2px solid var(--text-primary);
      outline-offset: 2px;
    }

    .btn-cookie-accept {
      font-family: var(--font-base);
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--bg-page);
      background: var(--text-primary);
      border: 1.5px solid var(--text-primary);
      border-radius: var(--radius-sm);
      padding: 7px 14px;
      cursor: pointer;
      white-space: nowrap;
      transition: opacity 0.15s;
    }

    .btn-cookie-accept:hover { opacity: 0.8; }
    .btn-cookie-accept:focus-visible {
      outline: 2px solid var(--brand-red);
      outline-offset: 2px;
    }

    /* ─── Preferences Modal ──────────────────────────────────────────── */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: oklch(0% 0 0 / 0.4);
      z-index: 200;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: var(--space-sm);
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.2s ease, visibility 0.2s ease;
    }

    .modal-overlay.open {
      opacity: 1;
      visibility: visible;
    }

    .modal {
      background: var(--bg-page);
      border-radius: var(--radius-md);
      width: 100%;
      max-width: 480px;
      padding: var(--space-lg) var(--space-md);
      box-shadow: 0 8px 40px oklch(0% 0 0 / 0.14);
      position: relative;
      transform: translateY(8px);
      transition: transform 0.2s ease;
    }

    .modal-overlay.open .modal {
      transform: translateY(0);
    }

    .modal-close {
      position: absolute;
      top: var(--space-sm);
      right: var(--space-sm);
      background: none;
      border: none;
      cursor: pointer;
      color: var(--text-muted);
      padding: 6px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: color 0.15s;
    }

    .modal-close:hover { color: var(--text-primary); }
    .modal-close:focus-visible {
      outline: 2px solid var(--text-primary);
      outline-offset: 2px;
    }

    .modal-close svg { width: 18px; height: 18px; stroke-width: 2; }

    .modal-title {
      font-size: 1.125rem;
      font-weight: 700;
      color: var(--text-primary);
      letter-spacing: -0.02em;
      margin-bottom: var(--space-xs);
    }

    .modal-desc {
      font-size: 0.875rem;
      color: var(--text-secondary);
      line-height: 1.6;
      margin-bottom: var(--space-md);
    }

    .pref-list {
      display: flex;
      flex-direction: column;
      gap: var(--space-sm);
      margin-bottom: var(--space-lg);
    }

    .pref-item {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: var(--space-sm);
      padding-bottom: var(--space-sm);
      border-bottom: 1px solid var(--border-subtle);
    }

    .pref-item:last-child { border-bottom: none; }

    .pref-label { font-size: 0.875rem; font-weight: 600; color: var(--text-primary); margin-bottom: 2px; }
    .pref-desc  { font-size: 0.8125rem; color: var(--text-secondary); line-height: 1.5; }

    /* Toggle switch */
    .toggle-wrap { flex-shrink: 0; position: relative; }

    .toggle-input {
      position: absolute;
      opacity: 0;
      width: 0;
      height: 0;
    }

    .toggle-label {
      display: block;
      width: 36px;
      height: 20px;
      background: var(--border-input);
      border-radius: 100px;
      cursor: pointer;
      transition: background 0.2s;
      position: relative;
    }

    .toggle-label::after {
      content: '';
      position: absolute;
      top: 3px;
      left: 3px;
      width: 14px;
      height: 14px;
      background: white;
      border-radius: 50%;
      transition: transform 0.2s;
      box-shadow: 0 1px 3px oklch(0% 0 0 / 0.2);
    }

    .toggle-input:checked + .toggle-label {
      background: var(--text-primary);
    }

    .toggle-input:checked + .toggle-label::after {
      transform: translateX(16px);
    }

    .toggle-input:disabled + .toggle-label {
      opacity: 0.5;
      cursor: not-allowed;
    }

    .toggle-input:focus-visible + .toggle-label {
      outline: 2px solid var(--text-primary);
      outline-offset: 2px;
    }

    .modal-footer {
      display: flex;
      justify-content: flex-end;
      gap: var(--space-xs);
    }

    .btn-save {
      font-family: var(--font-base);
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--bg-page);
      background: var(--text-primary);
      border: none;
      border-radius: var(--radius-sm);
      padding: 9px 20px;
      cursor: pointer;
      transition: opacity 0.15s;
    }

    .btn-save:hover { opacity: 0.8; }
    .btn-save:focus-visible {
      outline: 2px solid var(--brand-red);
      outline-offset: 2px;
    }

    /* ─── Responsive ─────────────────────────────────────────────────── */
    @media (max-width: 600px) {
      .page-wrapper {
        padding-top: var(--space-lg);
        padding-bottom: var(--space-xl);
      }

      .cookie-banner {
        flex-direction: column;
        align-items: flex-start;
        gap: var(--space-sm);
        padding: var(--space-sm);
      }

      .cookie-actions {
        width: 100%;
        justify-content: flex-end;
      }
    }

    @media (min-width: 900px) {
      .page-wrapper { padding-top: var(--space-2xl); }
    }
  </style>
</head>
<body>

  <!-- ─── Main Page ────────────────────────────────────────────────── -->
  <main class="page-wrapper" id="main-content">

    <!-- Logo -->
    <header class="logo-block" role="banner">
      <a href="/" class="logo-wordmark" aria-label="IdeaForum — Go to homepage">
        Id<span class="missing-e" aria-hidden="true"></span>aForum
      </a>
    </header>

    <!-- Error Content -->
    <section class="content-block" aria-labelledby="error-heading">

      <h1 class="error-heading" id="error-heading">Sorry, we can't find that.</h1>
      <p class="error-subline">Perhaps we can help you find the content you're looking for:</p>

      <!-- Search -->
      <form class="search-form" role="search" action="/search" method="get" id="search-form">
        <div class="search-field">
          <label for="search-input" class="visually-hidden">Search IdeaForum</label>
          <input
            id="search-input"
            class="search-input"
            type="search"
            name="q"
            placeholder="Search IdeaForum..."
            autocomplete="off"
            aria-label="Search IdeaForum"
          />
          <button type="submit" class="search-btn" aria-label="Submit search">
            <!-- Magnifying glass icon -->
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true" focusable="false">
              <circle cx="11" cy="11" r="8"/>
              <line x1="21" y1="21" x2="16.65" y2="16.65"/>
            </svg>
          </button>
        </div>
      </form>

      <!-- Error Code Bar -->
      <div class="error-code-bar" role="status" aria-label="Error status">
        <span class="error-code-text">HTTP Error 404</span>
      </div>

      <!-- Divider -->
      <div class="divider" role="separator" aria-hidden="true"></div>

      <!-- Next Steps -->
      <nav aria-label="Recovery options">
        <p class="next-steps-heading">What's next?</p>
        <ul class="next-steps-links">
          <li><a href="/">Go to the homepage</a></li>
          <li><a href="/help">Visit our Help Desk</a></li>
        </ul>
      </nav>

    </section>
  </main>

  <!-- ─── Cookie Banner ────────────────────────────────────────────── -->
  <div
    class="cookie-banner"
    id="cookie-banner"
    role="region"
    aria-label="Cookie consent"
    aria-live="polite"
  >
    <p class="cookie-text">
      This website utilizes technologies such as cookies to enable essential site functionality,
      as well as for analytics, personalization, and targeted advertising.
      To learn more, view the following link:
      <a href="/privacy-policy" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
    </p>
    <div class="cookie-actions">
      <button class="btn-cookie-manage" id="btn-manage-prefs" type="button">
        Manage Preferences
      </button>
      <button class="btn-cookie-accept" id="btn-accept-cookies" type="button">
        Accept All
      </button>
    </div>
  </div>

  <!-- ─── Cookie Preferences Modal ────────────────────────────────── -->
  <div
    class="modal-overlay"
    id="pref-modal"
    role="dialog"
    aria-modal="true"
    aria-labelledby="modal-title"
    aria-hidden="true"
  >
    <div class="modal" tabindex="-1" id="modal-panel">
      <button class="modal-close" id="modal-close" type="button" aria-label="Close preferences">
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true" focusable="false">
          <line x1="18" y1="6" x2="6" y2="18"/>
          <line x1="6" y1="6" x2="18" y2="18"/>
        </svg>
      </button>

      <h2 class="modal-title" id="modal-title">Cookie Preferences</h2>
      <p class="modal-desc">
        Choose which cookies you allow. Essential cookies are always active and cannot be disabled.
      </p>

      <div class="pref-list">

        <!-- Essential (locked on) -->
        <div class="pref-item">
          <div>
            <div class="pref-label">Essential</div>
            <div class="pref-desc">Required for core site functionality. Cannot be disabled.</div>
