      var overlay     = document.getElementById('pref-modal');
      var modalPanel  = document.getElementById('modal-panel');
      var btnClose    = document.getElementById('modal-close');
      var btnSave     = document.getElementById('btn-save-prefs');

      // Focusable elements within the modal
      function getFocusable() {
        return Array.from(modalPanel.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        )).filter(function (el) { return !el.disabled; });
      }

      function openModal() {
        overlay.classList.add('open');
        overlay.setAttribute('aria-hidden', 'false');
        modalPanel.focus();
        document.body.style.overflow = 'hidden';
